+# This function checks whether the dependency object passed in as the first
+# parameter mentions the package name passed in as the second parameter.
+sub dep_mentions_package {
+    my ($dep, $pkgname) = @_;
+
+    my $found = 0;
+    deps_iterate($dep, sub {
+        my $subdep = shift;
+
+        if (defined $subdep->{package} and $subdep->{package} eq $pkgname) {
+            $found = 1;
+            return 0;
+        }
+        return 1;
+    });
+
+    return $found;
+}
