+
+use v5.36;
+
+use Test::More;
+use Test::Dpkg qw(:paths);
+
+use File::Spec::Functions qw(rel2abs);
+use File::Path qw(make_path);
+
+use Dpkg::File;
+use Dpkg::IPC;
+
+plan tests => 12;
+
+my $srcdir = rel2abs($ENV{srcdir} || '.');
+my $tmpdir = rel2abs(test_get_temp_path());
+
+$ENV{$_} = rel2abs($ENV{$_}) foreach qw(DPKG_DATADIR DPKG_ORIGINS_DIR);
+
+# Delete variables that can affect the tests.
+delete $ENV{$_} foreach grep { m/^DEB_/ } keys %ENV;
+
+# Set architecture variables to not require dpkg nor gcc.
+$ENV{DEB_BUILD_ARCH} = 'amd64';
+$ENV{DEB_HOST_ARCH} = 'amd64';
+
+my $admindir = "$tmpdir/admindir";
+my $pkgdir = "$tmpdir/pkg";
+
+make_path($admindir, "$pkgdir/debian");
+
+sub gen_status
+{
+    my (@pkgs) = @_;
+
+    my $status = q{};
+    foreach my $pkg (@pkgs) {
+        $status .= <<"STATUS";
+Package: $pkg
+Status: install ok installed
+Version: 1.0
+Architecture: amd64
+
+STATUS
+    }
+
+    file_dump("$admindir/status", $status);
+}
+
+sub gen_control
+{
+    my (@build_depends) = @_;
+
+    file_dump("$pkgdir/debian/control", <<"CONTROL");
+Source: test-pkg
+Maintainer: Dpkg Developers <debian-dpkg\@lists.debian.org>
+Build-Depends: @{[join(', ', @build_depends)]}
+
+Package: test-pkg
+Architecture: any
+Description: test package
+CONTROL
+}
+
+sub test_checkbuilddeps
+{
+    my (%opts) = @_;
+
+    my $stderr;
+
+    local $ENV{DEB_VENDOR} = $opts{vendor};
+
+    chdir $pkgdir;
+    spawn(
+        exec => [
+            $ENV{PERL} // $^X, "$srcdir/dpkg-checkbuilddeps.pl",
+            "--admindir=$admindir",
+            '-a', 'amd64',
+            @{$opts{args} // []},
+        ],
+        error_to_string => \$stderr,
+        wait_child => 1,
+        no_check => 1,
+    );
+    chdir $tmpdir;
+
+    is($? >> 8, $opts{expect}, "$opts{desc} (exit status)");
+    if ($opts{expect_unmet}) {
+        like($stderr, qr/unmet build dependencies:.*\b\Q$opts{expect_unmet}\E\b/,
+             "$opts{desc} (unmet dependency on $opts{expect_unmet})");
+    } else {
+        is($stderr, q{}, "$opts{desc} (no output)");
+    }
+}
+
+# On Ubuntu, require coreutils-from-uutils when there is no build
+# dependency on coreutils-from-gnu.
+
+gen_control('test-dep');
+gen_status('build-essential', 'test-dep');
+test_checkbuilddeps(
+    desc => 'ubuntu, missing coreutils-from-uutils',
+    vendor => 'Ubuntu',
+    expect => 1,
+    expect_unmet => 'coreutils-from-uutils',
+);
+
+gen_control('test-dep');
+gen_status('build-essential', 'test-dep', 'coreutils-from-uutils');
+test_checkbuilddeps(
+    desc => 'ubuntu, coreutils-from-uutils installed',
+    vendor => 'Ubuntu',
+    expect => 0,
+);
+
+gen_control('test-dep', 'coreutils-from-gnu');
+gen_status('build-essential', 'test-dep', 'coreutils-from-gnu');
+test_checkbuilddeps(
+    desc => 'ubuntu, build depends on coreutils-from-gnu',
+    vendor => 'Ubuntu',
+    expect => 0,
+);
+
+gen_control('test-dep | coreutils-from-gnu');
+gen_status('build-essential', 'test-dep');
+test_checkbuilddeps(
+    desc => 'ubuntu, build depends on alternative with coreutils-from-gnu',
+    vendor => 'Ubuntu',
+    expect => 0,
+);
+
+gen_control('test-dep');
+gen_status('build-essential', 'test-dep');
+test_checkbuilddeps(
+    desc => 'debian, no coreutils requirement',
+    vendor => undef,
+    expect => 0,
+);
+
+gen_control('test-dep');
+gen_status('build-essential', 'test-dep');
+test_checkbuilddeps(
+    desc => 'ubuntu, builtin build dependencies ignored',
+    vendor => 'Ubuntu',
+    args => ['-I'],
+    expect => 0,
+);
